const D = { energy: .6, density: .5, hue: 32, speed: 1, scale: 1, x: .5, y: .5, evap: .5, act: 'cycle', style: 'field_plate', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// RESCUE NOTE: v1 read as an empty cream field with three specks at lum .734 —
// the classic too-pale failure, twice over. (a) 240 ants on a 168x64 grid is
// ~20x sparser than the physarum reference, so no trail network ever formed;
// (b) the plate ground sat at v=.84, so what little ink there was had nowhere
// to go. Fixed with: 4x the ants, several nests so the network spans the frame,
// physarum-calibrated deposit/decay, a mid-key toned ground, and — the
// structural fix — AUTO-EXPOSURE off the field's own smoothed mean, which makes
// a blank frame impossible regardless of how the params are driven.

const GW = Math.max(360, Math.min(720, Math.round(width / 2.4))), GH = Math.max(64, Math.round(GW * height / width)), NCELL = GW * GH;
const MAXA = 1400, MAXC = 16, MAXN = 3;
const cl = (v, a, b) => v < a ? a : v > b ? b : v;
const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };
const hsv = (h, s, v) => {
  h = ((h % 360) + 360) % 360 / 60; const c = v * s, xx = c * (1 - Math.abs(h % 2 - 1)), m = v - c; let r, g2, b2;
  if (h < 1) { r = c; g2 = xx; b2 = 0; } else if (h < 2) { r = xx; g2 = c; b2 = 0; } else if (h < 3) { r = 0; g2 = c; b2 = xx; }
  else if (h < 4) { r = 0; g2 = xx; b2 = c; } else if (h < 5) { r = xx; g2 = 0; b2 = c; } else { r = c; g2 = 0; b2 = xx; }
  return [(r + m) * 255, (g2 + m) * 255, (b2 + m) * 255];
};

if (!S.tr || S.gw !== GW || S.gh !== GH || S.seedUsed !== P.seed) {
  if (S.g && S.g.remove) S.g.remove();
  S.g = createGraphics(GW, GH); S.g.pixelDensity(1);
  S.gw = GW; S.gh = GH; S.seedUsed = P.seed; S.tick = 0; S.step = 0; S.inited = 0; S.burned = 0; S.ex = null;
  S.tr = new Float32Array(NCELL); S.tmp = new Float32Array(NCELL); S.grain = new Float32Array(NCELL);
  for (let i = 0; i < NCELL; i++) S.grain[i] = fr(i * 1.31 + 7);
  S.ax = new Float32Array(MAXA); S.ay = new Float32Array(MAXA); S.ad = new Float32Array(MAXA);
  S.ld = new Uint8Array(MAXA); S.an = new Uint8Array(MAXA);
  S.cx = new Float32Array(MAXC); S.cy = new Float32Array(MAXC); S.cAmt = new Float32Array(MAXC); S.cMax = new Float32Array(MAXC); S.cAl = new Uint8Array(MAXC);
}

const tr = S.tr, tmp = S.tmp, grain = S.grain, ax = S.ax, ay = S.ay, ad = S.ad, ld = S.ld, an = S.an;
const cx = S.cx, cy = S.cy, cAmt = S.cAmt, cMax = S.cMax, cAl = S.cAl;
S.tick = (S.tick || 0) + 1;
// salted on S.step so the burn-in is not a degenerate loop
const rnd = k => { const s = Math.sin(k * 12.9898 + S.step * .6180339 + P.seed * 7.13) * 43758.5453; return s - Math.floor(s); };
const st = P.style;

// ---- several nests, so the trunk network spans the whole plate --------------
const NN = 1 + Math.round(cl(P.density, 0, 1) * (MAXN - 1));
const nxs = [], nys = [];
for (let q = 0; q < NN; q++) {
  const a = q * 2.3999 + .7, rr = q === 0 ? 0 : .24 + .12 * fr(q * 13);
  nxs.push(cl((P.x + Math.cos(a) * rr) * GW, 4, GW - 5));
  nys.push(cl((P.y + Math.sin(a) * rr * .8) * GH, 4, GH - 5));
}

// ---- act: multi-minute foraging regime ------------------------------------
let forage;
if (P.act === 'glut') forage = 1.8;
else if (P.act === 'famine') forage = .38;
else forage = .45 + 1.35 * (.5 + .5 * Math.sin(K.t * .0121 + .8 * Math.sin(K.t * .0043 + 1.4)));

const nAnts = Math.min(MAXA, Math.round(280 + cl(P.density, 0, 1) * 900));
while (S.inited < nAnts) {
  const k = S.inited, nq = k % NN;
  ax[k] = nxs[nq]; ay[k] = nys[nq]; ad[k] = fr(k * 3 + 1) * 6.283; ld[k] = 0; an[k] = nq; S.inited++;
}
const useN = Math.min(nAnts, S.inited);
const SP = (.35 + P.energy * .55) * (.45 + P.speed * .8);
const SD = 2.6 + P.scale * 2.2, SA = .68;
const dep = 3.0 + P.energy * 4.0;          // laden: the recruitment trunk trail
// searchers mark only FAINTLY. v1 had this at .22*dep and 730 ants: the uniform
// exploratory haze then swamped the trunk trails, the gradient went to noise, and
// the whole field settled to a flat statistically-stationary wash (measured field
// mean == exactly the haze equilibrium, laden ants == 0%). Stigmergy needs the
// signal above the marking.
const expl = dep * .07;
const ev = .9880 - cl(P.evap, 0, 1) * .012;
// the foraging RANGE: the annulus the colony works. Caches are seeded on it and
// searchers are held to it — see the range-keeping term below.
const RANGE = GH * .41 * (.6 + cl(P.scale, .35, 2.2) * .4);
const nWantC = 3 + Math.round(cl(P.density, 0, 1) * 9);
const trAt = (gx, gy) => {
  let ix = Math.floor(gx), iy = Math.floor(gy);
  if (ix < 0) ix = 0; if (iy < 0) iy = 0; if (ix >= GW) ix = GW - 1; if (iy >= GH) iy = GH - 1;
  return tr[iy * GW + ix];
};

// ---- one step of the colony -------------------------------------------------
const simStep = () => {
  S.step = (S.step || 0) + 1;
  // caches deplete, vanish, respawn elsewhere => the network never converges
  let nC = 0;
  for (let c = 0; c < MAXC; c++) if (cAl[c]) nC++;
  if (nC < nWantC) {
    for (let c = 0; c < MAXC; c++) if (!cAl[c]) {
      // v1 scored placement by MAXIMUM distance from the nests, so every cache
      // landed in a far corner, no ant ever reached one, and the colony never
      // foraged at all. Seed them on the foraging range instead, spaced apart.
      let bx = GW * .5, by = GH * .5, best = -1e9;
      for (let q = 0; q < 10; q++) {
        const px2 = 8 + rnd(c * 19 + q * 3 + 1) * (GW - 16), py2 = 8 + rnd(c * 19 + q * 3 + 2) * (GH - 16);
        let dn = 1e9;
        for (let o = 0; o < NN; o++) dn = Math.min(dn, Math.hypot(px2 - nxs[o], py2 - nys[o]));
        let dc = 1e9;
        for (let o = 0; o < MAXC; o++) if (cAl[o]) dc = Math.min(dc, Math.hypot(px2 - cx[o], py2 - cy[o]));
        if (dc > 900) dc = 40;
        const sc2 = Math.min(dc, 26) - Math.abs(dn - RANGE) * 1.1;
        if (sc2 > best) { best = sc2; bx = px2; by = py2; }
      }
      cAl[c] = 1; cx[c] = bx; cy[c] = by;
      cMax[c] = (250 + rnd(c * 23 + 5) * 650) * forage; cAmt[c] = cMax[c];
      break;
    }
  }
  // ants
  for (let k = 0; k < useN; k++) {
    const nq = an[k], nx0 = nxs[nq], ny0 = nys[nq];
    let d = ad[k];
    if (ld[k]) {
      const ta = Math.atan2(ny0 - ay[k], nx0 - ax[k]);
      let da = ta - d; while (da > Math.PI) da -= 6.283; while (da < -Math.PI) da += 6.283;
      d += da * .22 + (rnd(k * 3 + 1) - .5) * .1;
      if (Math.hypot(ax[k] - nx0, ay[k] - ny0) < 2.2) { ld[k] = 0; d = rnd(k * 7 + 3) * 6.283; }
    } else {
      const c = trAt(ax[k] + Math.cos(d) * SD, ay[k] + Math.sin(d) * SD);
      const l = trAt(ax[k] + Math.cos(d - SA) * SD, ay[k] + Math.sin(d - SA) * SD);
      const r = trAt(ax[k] + Math.cos(d + SA) * SD, ay[k] + Math.sin(d + SA) * SD);
      const turn = .22 + P.energy * .26;
      if (l > c && l >= r) d -= turn; else if (r > c && r > l) d += turn;
      else if (c <= l && c <= r) d += (rnd(k * 3 + 5) - .5) * .9;
      d += (rnd(k * 3 + 2) - .5) * (.22 + (1 - P.energy) * .4);
      // range-keeping: push outward near the nest, pull back beyond the range.
      // Without this the searchers random-walk to the frame edge and never come
      // home, the colony starves, and the trail network decays to nothing over
      // ~25s (measured: motion fell to 0.0026, under the 0.004 gate).
      {
        const dh = Math.hypot(ax[k] - nx0, ay[k] - ny0);
        const rad = (dh - RANGE * 1.3) / (RANGE * .9);
        const oa = Math.atan2(ay[k] - ny0, ax[k] - nx0);
        const tgt = rad < 0 ? oa : oa + Math.PI;
        let od = tgt - d; while (od > Math.PI) od -= 6.283; while (od < -Math.PI) od += 6.283;
        d += od * .16 * Math.min(1, Math.abs(rad));
      }
      for (let c2 = 0; c2 < MAXC; c2++) {
        if (!cAl[c2] || cAmt[c2] <= 0) continue;
        if (Math.hypot(ax[k] - cx[c2], ay[k] - cy[c2]) < 5.5 + P.scale * 1.5) {
          cAmt[c2] -= 1; ld[k] = 1; d += Math.PI;
          if (cAmt[c2] <= 0) cAl[c2] = 0;
          break;
        }
      }
    }
    ad[k] = d;
    let px2 = ax[k] + Math.cos(d) * SP, py2 = ay[k] + Math.sin(d) * SP;
    if (px2 < 1) { px2 = 1; ad[k] = Math.PI - d; } if (px2 > GW - 1) { px2 = GW - 1; ad[k] = Math.PI - d; }
    if (py2 < 1) { py2 = 1; ad[k] = -d; } if (py2 > GH - 1) { py2 = GH - 1; ad[k] = -d; }
    ax[k] = px2; ay[k] = py2;
    const gi2 = Math.min(GH - 1, Math.max(0, Math.floor(py2))) * GW + Math.min(GW - 1, Math.max(0, Math.floor(px2)));
    tr[gi2] += ld[k] ? dep : expl;
  }
  // evaporation + diffusion: trails to spent caches prune themselves
  for (let y = 0; y < GH; y++) {
    const yc = y * GW, yu = Math.max(0, y - 1) * GW, yd = Math.min(GH - 1, y + 1) * GW;
    for (let x = 0; x < GW; x++) {
      const i = yc + x, xl = Math.max(0, x - 1), xr = Math.min(GW - 1, x + 1);
      tmp[i] = (tr[i] * .88 + (tr[yc + xl] + tr[yc + xr] + tr[yu + x] + tr[yd + x]) * .03) * ev;
    }
  }
  tr.set(tmp);
};

// arrive with a network already laid
if (!S.burned) { S.burned = 1; for (let q = 0; q < 220; q++) simStep(); }
simStep();

// ---- auto-exposure: normalise off the field's own smoothed mean -------------
// This is what makes "an empty field with three specks" structurally impossible:
// whatever the absolute pheromone level, the trails always land in the visible
// part of the curve. The GROUND supplies the luminance; v only drives the ink.
let sum = 0;
for (let i = 0; i < NCELL; i++) sum += tr[i];
const mn2 = sum / NCELL;
S.ex = (S.ex == null || !isFinite(S.ex)) ? mn2 : S.ex * .96 + mn2 * .04;
const NORM = 1 / Math.max(.5, S.ex * 2.4);

// ---- render the pheromone field --------------------------------------------
const g = S.g; g.loadPixels(); const pix = g.pixels;
const expo = (.7 + P.energy * .8) * (.8 + K.intensity * .3 + A.rms * .4);
const hb = P.hue;
for (let i = 0; i < NCELL; i++) {
  const v0 = tr[i] * NORM * expo;
  const v = v0 / (v0 + 1);
  const gn = grain[i];
  const o = 4 * i; let r, g2, b;
  if (st === 'pheromone') {
    const m = Math.min(1, v * 1.5), cold = 1 - Math.min(1, m * 3.2);
    r = Math.min(255, m * 2.55 * 255) + cold * 26;
    g2 = Math.max(0, Math.min(255, (m * 2.1 - .5) * 255)) + cold * 18;
    b = Math.max(0, Math.min(255, (m * 3.3 - 2.3) * 255)) + cold * 88;
  } else if (st === 'darkfield') {
    const c0 = hsv(hb + 196, .62, .15 + gn * .04);
    const gl = hsv(hb + 168 - v * 44, Math.max(0, .7 - v * .55), Math.min(1.1, v * 1.55));
    r = c0[0] + gl[0]; g2 = c0[1] + gl[1]; b = c0[2] + gl[2];
  } else if (st === 'ink') {
    const p2 = (.58 - Math.min(.5, v * .56)) * (1 - gn * .06);
    r = p2 * 244; g2 = p2 * 240; b = p2 * 231;
  } else {
    // field_plate: a TONED buff plate — not a cream page
    const c0 = hsv(hb + 16, .22 + gn * .06, .48 - gn * .05);
    const ink = hsv(hb - 10, .70, .13);
    const m = Math.min(.94, v * 1.08);
    r = c0[0] * (1 - m) + ink[0] * m; g2 = c0[1] * (1 - m) + ink[1] * m; b = c0[2] * (1 - m) + ink[2] * m;
  }
  pix[o] = r < 0 ? 0 : r > 255 ? 255 : r;
  pix[o + 1] = g2 < 0 ? 0 : g2 > 255 ? 255 : g2;
  pix[o + 2] = b < 0 ? 0 : b > 255 ? 255 : b;
  pix[o + 3] = 255;
}
g.updatePixels();

push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(g, 0, 0, width, height);
pop();

// ---- nodes + ants on the plate ---------------------------------------------
const SX = width / GW, SY = height / GH, u = Math.min(width, height);
const mk = (3.5 + P.density * 6) * u * .0022 * (.6 + P.scale * .6);
push();
if (st !== 'pheromone') {
  const inkH = st === 'darkfield' ? P.hue + 150 : P.hue - 6;
  const inkS = st === 'ink' ? 6 : st === 'darkfield' ? 40 : 58;
  const inkB = st === 'darkfield' ? 100 : st === 'ink' ? 18 : 16;
  // food caches with a depletion gauge
  for (let c = 0; c < MAXC; c++) {
    if (!cAl[c]) continue;
    const X = cx[c] * SX, Y = cy[c] * SY, f = Math.max(0, Math.min(1, cAmt[c] / Math.max(1, cMax[c])));
    noFill(); strokeWeight(Math.max(1, u * .0016)); stroke(inkH, inkS, inkB, 72);
    ellipse(X, Y, mk * 3.4, mk * 3.4);
    strokeWeight(Math.max(1.4, u * .003)); stroke(inkH, inkS, st === 'darkfield' ? 100 : 34, 92);
    arc(X, Y, mk * 4.6, mk * 4.6, -1.5708, -1.5708 + f * 6.283);
    noStroke(); fill(inkH, inkS, inkB, 60 + f * 34); ellipse(X, Y, mk * 1.5 * (.4 + f * .8), mk * 1.5 * (.4 + f * .8));
  }
  // nests
  for (let q = 0; q < NN; q++) {
    const NX = nxs[q] * SX, NY = nys[q] * SY, br = 1 + K.pulse * .16 + A.bass * .22;
    noFill(); strokeWeight(Math.max(1.4, u * .0028)); stroke(inkH, inkS, inkB, 90);
    ellipse(NX, NY, mk * 5.2 * br, mk * 5.2 * br);
    strokeWeight(Math.max(1, u * .0015)); stroke(inkH, inkS, inkB, 55);
    ellipse(NX, NY, mk * 8 * br, mk * 8 * br);
    for (let i = 0; i < 6; i++) { const a = i * 1.047 + K.t * .04; line(NX + Math.cos(a) * mk * 2.6, NY + Math.sin(a) * mk * 2.6, NX + Math.cos(a) * mk * 4, NY + Math.sin(a) * mk * 4); }
  }
  // ants — simulate them all, draw a representative stride of them (point budget)
  const aw = Math.max(1.1, u * .0021 * (.7 + P.scale * .5));
  const stride = Math.max(1, Math.ceil(useN / 240));
  strokeWeight(aw); strokeCap(ROUND);
  for (let k = 0; k < useN; k += stride) {
    const X = ax[k] * SX, Y = ay[k] * SY, dd = ad[k], L = aw * 1.7;
    if (ld[k]) stroke(inkH + 18, inkS * .8, st === 'darkfield' ? 100 : inkB + 26, 96);
    else stroke(inkH, inkS, st === 'darkfield' ? 88 : inkB + 8, 72);
    line(X - Math.cos(dd) * L, Y - Math.sin(dd) * L, X + Math.cos(dd) * L, Y + Math.sin(dd) * L);
  }
}
pop();
blendMode(BLEND);
drawingContext.shadowBlur = 0;
